const tabEl = document.getElementById('messages-tab');
tabEl.addEventListener('show.bs.tab', async event => {
  if (!tabEl.dataset.loaded) {
    const res = await fetch('/api/messages');
    document.getElementById('messages').innerHTML = await res.text();
    tabEl.dataset.loaded = 'true';
  }
});

